const dns = require("dns");
const net = require("net");
// Node.js's dns from an npm package: lookups through the system resolver, the Resolver's server
// list, and the errors packages see (no network needed). Prints what it found; the same package
// under Node.js prints the same.
module.exports = async function run() {
  const lookup = (...a) => new Promise((res) => dns.lookup(...a, (err, address, family) => res(err ? `${err.code} ${err.syscall} ${err.hostname}` : `${JSON.stringify(address)} ${family}`)));
  console.log("lookup ip", await lookup("127.0.0.1"), await lookup("::1"));
  console.log("lookup localhost v4", await lookup("localhost", { family: 4 }));
  console.log("lookup all", await lookup("localhost", { all: true, family: 4 }));
  console.log("lookup missing", await lookup("nothing-here.invalid"));
  console.log("promises lookup", JSON.stringify(await dns.promises.lookup("127.0.0.1")));
  try {
    await dns.promises.lookup("nothing-here.invalid");
  } catch (e) {
    console.log("promises missing", e.code, e.errno, e.message);
  }
  try {
    dns.lookup("x", { family: 5 }, () => {});
  } catch (e) {
    console.log("bad family", e.code);
  }
  const r = new dns.Resolver();
  console.log("servers", Array.isArray(r.getServers()), r.getServers().length > 0);
  r.setServers(["1.2.3.4", "[2001:db8::1]:5353", "5.6.7.8:53"]);
  console.log("setServers", JSON.stringify(r.getServers()));
  try {
    r.setServers(["not an ip"]);
  } catch (e) {
    console.log("setServers invalid", e.code);
  }
  console.log("isIP", net.isIP("1.2.3.4"), net.isIP("::1"), net.isIP("nope"), net.isIPv6("2001:db8::1"));
  console.log("constants", dns.ADDRCONFIG > 0, dns.NOTFOUND, dns.NODATA, typeof dns.lookupService, typeof dns.resolve4);
  await new Promise((res) => dns.lookupService("127.0.0.1", 0, (err, host) => { console.log("lookupService", err ? err.code : typeof host); res(); }));
  try {
    r.resolve4("bad..name", () => {});
  } catch (e) {
    console.log("resolve throws", e.code);
  }
  await new Promise((res) => r.resolve4("bad..name", (err) => { console.log("resolve bad name", err && err.code); res(); }));
  const offline = new dns.Resolver({ timeout: 50, tries: 1 });
  offline.setServers(["127.0.0.1:1"]);
  await new Promise((res) => offline.resolve4("example.com", (err) => { console.log("resolve no server", err && err.code, err && err.syscall); res(); }));
};
